import { Children, Fragment, isValidElement, type ComponentType, useCallback, useEffect, useLayoutEffect, useRef, useState, type ReactNode } from 'react';
import { ArrowUp, Mic, Plus, Square } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useAttachments } from './attachments';
import { ContextMeter } from './agent-limits';

/* What every composer variant shares: the props contract, the textarea behaviour (auto-grow, Enter / Shift+Enter /
 * Esc) and the small buttons and status line. Lives apart from composers.tsx so variant files (kit/variants/*)
 * can import it without a cycle through the variant registry. */
export interface ComposerProps {
  value: string;
  onChange: (v: string) => void;
  onSend: (v: string) => void;
  onStop?: () => void;
  busy?: boolean;
  placeholder?: string;
  /** Model picker, shown where the variant has room. */
  model?: ReactNode;
  /** Tool chips (mode toggles, dataset…). */
  tools?: ReactNode;
  /** Two spans (left, right) for the status line under or inside the composer. */
  status?: ReactNode;
  /** Context window used, 0–100: the context ring, which opens the Agent Limits Card. */
  context?: number;
  /** Box: its field takes @mentions of files, people, sources and tools, as chips (an @ button and menu). */
  mentions?: boolean;
  /** Branch and project for the Panel's top rail. */
  branch?: string;
  project?: string;
  className?: string;
}

/** What each variant renders from: the props plus the attachment queue, owned by <Composer> so switching variant keeps the files. */
export type VariantProps = ComposerProps & { placeholder: string; att: ReturnType<typeof useAttachments> };

/** Grows with its text up to 8 lines (a quarter of the viewport on short screens, never under 4 lines), then
 * scrolls inside, like ChatGPT. */
export const fieldMaxHeight = () => Math.max(96, Math.min(192, Math.round(window.innerHeight * 0.25)));

/** Shared behaviour: an auto-growing textarea, Enter to send (Shift+Enter for a newline), Esc to stop. */
export function useField({ value, busy, onSend, onStop }: Pick<ComposerProps, 'value' | 'busy' | 'onSend' | 'onStop'>) {
  const ref = useRef<HTMLTextAreaElement>(null);
  // Before paint, so the field never shows a stale height; composers that move the field call fit() again.
  const fit = useCallback(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = `${Math.min(el.scrollHeight, fieldMaxHeight())}px`;
  }, []);
  useLayoutEffect(fit, [value, fit]);
  const submit = () => {
    if (!busy && value.trim()) onSend(value);
  };
  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement | HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      submit();
    }
    if (e.key === 'Escape' && busy) onStop?.();
  };
  return { ref, submit, onKeyDown, fit };
}

export const AddButton = ({ className, onClick }: { className?: string; onClick?: () => void }) => (
  <button type="button" aria-label="Add attachment" onClick={onClick} className={cn('grid size-9 shrink-0 place-items-center rounded-full bg-ai-chat-composer-add-background text-foreground-icon-primary transition-[background-color,scale] hover:bg-ai-chat-composer-add-hover-background active:scale-[0.96]', className)}>
    <Plus className="size-5" />
  </button>
);

/* Dictation: the browser's speech recognition writes into the field as you talk; where there is none, or the mic is
 * refused, a short phrase is "heard" word by word instead so the button always does something. Click again to stop. */
type Recognition = { continuous: boolean; interimResults: boolean; lang: string; start(): void; stop(): void; abort(): void; onresult: ((e: { results: ArrayLike<ArrayLike<{ transcript: string }>> }) => void) | null; onerror: (() => void) | null; onend: (() => void) | null };
const recognitionCtor = () => {
  const w = window as unknown as { SpeechRecognition?: new () => Recognition; webkitSpeechRecognition?: new () => Recognition };
  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
};
const HEARD = ['Summarize what changed since yesterday', 'Draft a short reply that says we ship on Friday', 'List the risks before we merge this'];

export function useDictation(value: string, onChange: (v: string) => void) {
  const [listening, setListening] = useState(false);
  const live = useRef({ value, onChange });
  live.current = { value, onChange };
  const session = useRef<{ rec: Recognition | null; timer: number | null; heard: boolean } | null>(null);
  const turn = useRef(0);

  const stop = useCallback(() => {
    const s = session.current;
    session.current = null;
    if (s?.timer) window.clearInterval(s.timer);
    try {
      s?.rec?.stop();
    } catch {
      /* already stopped */
    }
    setListening(false);
  }, []);

  const start = useCallback(() => {
    if (session.current) return;
    const base = live.current.value.trim();
    const join = (t: string) => (base && t ? `${base} ${t}` : base || t);
    const s: { rec: Recognition | null; timer: number | null; heard: boolean } = { rec: null, timer: null, heard: false };
    session.current = s;
    setListening(true);
    const simulate = () => {
      if (session.current !== s) return;
      s.rec = null;
      const words = HEARD[turn.current++ % HEARD.length].split(' ');
      let i = 0;
      s.timer = window.setInterval(() => {
        live.current.onChange(join(words.slice(0, ++i).join(' ')));
        if (i >= words.length) stop();
      }, 180);
    };
    const Ctor = recognitionCtor();
    if (!Ctor) return simulate();
    try {
      const rec = new Ctor();
      rec.continuous = true;
      rec.interimResults = true;
      rec.lang = navigator.language || 'en-US';
      rec.onresult = (e) => {
        let t = '';
        for (let i = 0; i < e.results.length; i++) t += e.results[i][0]?.transcript ?? '';
        s.heard = true;
        live.current.onChange(join(t.trim()));
      };
      // Refused, offline or no device: fall back to the simulation; a real session that ended just stops.
      rec.onerror = () => !s.heard && simulate();
      rec.onend = () => {
        if (session.current === s && !s.timer) (s.heard ? stop() : simulate());
      };
      s.rec = rec;
      rec.start();
    } catch {
      simulate();
    }
  }, [stop]);

  useEffect(() => stop, [stop]);
  return { listening, toggle: () => (session.current ? stop() : start()) };
}

/** Dictate into the field; pulses while listening. */
export function MicButton({ value, onChange, className }: { value: string; onChange: (v: string) => void; className?: string }) {
  const { listening, toggle } = useDictation(value, onChange);
  return (
    <button
      type="button"
      aria-label={listening ? 'Stop dictation' : 'Dictate'}
      aria-pressed={listening}
      onClick={toggle}
      className={cn(
        'relative hidden size-9 shrink-0 place-items-center rounded-full transition-colors sm:grid',
        listening ? 'bg-red-500/10 text-red-500 hover:bg-red-500/15' : 'text-foreground-icon-secondary hover:bg-background-tertiary-default hover:text-foreground-icon-primary',
        className,
      )}
    >
      {listening && <span aria-hidden className="absolute inset-0 animate-ping rounded-full bg-red-500/20 motion-reduce:animate-none" />}
      <Mic className="relative size-[18px]" />
    </button>
  );
}

export function SendButton({ busy, disabled, onStop, className, stopClassName }: { busy?: boolean; disabled: boolean; onStop?: () => void; className?: string; stopClassName?: string }) {
  return busy ? (
    <button type="button" onClick={onStop} aria-label="Stop generating" className={cn('grid size-9 shrink-0 place-items-center rounded-full bg-background-tertiary-default text-foreground-icon-primary transition-colors hover:bg-background-tertiary-hover', stopClassName)}>
      <Square className="size-3.5 fill-current" />
    </button>
  ) : (
    <button type="submit" aria-label="Send message" disabled={disabled} className={cn('grid size-9 shrink-0 place-items-center rounded-full bg-text-primary text-background-primary-default transition-[opacity,scale] active:scale-95 disabled:opacity-30', className)}>
      <ArrowUp className="size-5" />
    </button>
  );
}

/**
 * The line under a composer: templates pass two spans (left, right). With `context`, the ring takes the far
 * right and the right span sits just before it.
 */
export const Status = ({ children, context, className }: { children?: ReactNode; context?: number; className?: string }) => {
  if (!children && context === undefined) return null;
  // `status` usually arrives as a fragment: unwrap it to reach the two spans.
  const flat = Children.toArray(children).flatMap((c) => (isValidElement<{ children?: ReactNode }>(c) && c.type === Fragment ? Children.toArray(c.props.children) : [c]));
  const [left, ...right] = flat;
  return (
    <div className={cn('flex h-[26px] items-center justify-between gap-3 px-2 text-body-2-medium text-text-tertiary [&_svg]:size-4 [&_svg]:text-foreground-icon-tertiary', className)}>
      {left ?? <span />}
      <span className="flex min-w-0 items-center gap-2">
        {right}
        {context !== undefined && <ContextMeter percent={context} className="-me-2" />}
      </span>
    </div>
  );
};

export const Field = ({ field, value, onChange, placeholder, className }: { field: ReturnType<typeof useField>; value: string; onChange: (v: string) => void; placeholder: string; className?: string }) => (
  <textarea
    ref={field.ref}
    rows={1}
    value={value}
    onChange={(e) => onChange(e.target.value)}
    onKeyDown={field.onKeyDown}
    placeholder={placeholder}
    aria-label="Message"
    className={cn('scrollbar-thin w-full resize-none bg-transparent text-body-regular leading-6 text-text-primary caret-text-primary outline-none placeholder:text-text-tertiary', className)}
  />
);

/**
 * Makes a composer view standalone: it owns its attachment queue and clears it on send, as a chat composer
 * should. Every composer file exports both the view (for a switcher that shares one queue) and this wrapped form.
 */
export function withAttachments(View: ComponentType<VariantProps>) {
  function StandaloneComposer({ placeholder = 'Ask me anything', ...p }: ComposerProps) {
    const att = useAttachments();
    const onSend = (v: string) => {
      p.onSend(v);
      att.clear();
    };
    return <View {...p} placeholder={placeholder} onSend={onSend} att={att} />;
  }
  StandaloneComposer.displayName = View.displayName ?? View.name.replace(/View$/, '');
  return StandaloneComposer;
}

import { useEffect, useState, type CSSProperties, type ReactNode } from 'react';
import { cn } from '@/lib/utils';

/* The agentic primitives (Agent Thinking, Composer Loader, the agent-log trail),
 * kept to the variants the templates use. Keyframes live in styles/templates.css. */

const TONES = {
  subtle: 'var(--color-text-tertiary)',
  default: 'var(--color-text-secondary)',
  primary: 'var(--color-text-primary)',
};

/* ------------------------------------------------------------------ Agent Thinking */

const DOTS_GRID = 3;
const DOTS_SIZE = 4;
const DOTS_TRAIL = 0.3;
const DOTS_MIN = 0.12;
const DOTS_SEED = [0.55, 0.3, 0.15, 0.85, 0.55, 0.3, 1, 0.85, 0.55];

function dotOpacities(phase: number) {
  const m = DOTS_GRID - 1;
  return Array.from({ length: DOTS_GRID * DOTS_GRID }, (_, i) => {
    // Diagonal wavefront, top-left → bottom-right; the scalar is compressed so the wrap reads as re-entry.
    const s = (((i % DOTS_GRID) + Math.floor(i / DOTS_GRID)) / (2 * m)) * (DOTS_GRID / (DOTS_GRID + 1));
    const behind = (phase - s + 1) % 1;
    return DOTS_MIN + (1 - DOTS_MIN) * Math.max(0, 1 - behind / DOTS_TRAIL) ** 1.5;
  });
}

function WaveDots() {
  const [opacities, setOpacities] = useState(DOTS_SEED);
  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    let phase = 0;
    const id = window.setInterval(() => {
      phase = (phase + 1 / 8) % 1;
      setOpacities(dotOpacities(phase));
    }, 80);
    return () => window.clearInterval(id);
  }, []);
  return (
    <span aria-hidden className="grid shrink-0" style={{ gridTemplateColumns: `repeat(${DOTS_GRID}, ${DOTS_SIZE}px)`, gap: 2 }}>
      {opacities.map((o, i) => (
        <span key={i} className="rounded-[1px] bg-current" style={{ width: DOTS_SIZE, height: DOTS_SIZE, opacity: o, transition: 'opacity 220ms ease' }} />
      ))}
    </span>
  );
}

const STARS = [
  { x: 50, y: 46, s: 1 },
  { x: 18, y: 22, s: 0.55 },
  { x: 82, y: 26, s: 0.45 },
  { x: 78, y: 76, s: 0.55 },
  { x: 22, y: 78, s: 0.4 },
];

function Stars() {
  const box = 21;
  return (
    <span aria-hidden className="sui-agent-thinking-stars relative block shrink-0" style={{ width: box, height: box }}>
      {STARS.map((st, i) => {
        const size = 14 * st.s;
        return (
          <svg
            key={i}
            viewBox="0 0 24 24"
            className="sui-agent-thinking-star absolute"
            style={{ width: size, height: size, left: `${st.x}%`, top: `${st.y}%`, marginLeft: -size / 2, marginTop: -size / 2, animationDuration: '1.4s', animationDelay: `${(i * 1.4 * 0.7) / 5}s` }}
          >
            <path d="M12 0C13 7 17 11 24 12C17 13 13 17 12 24C11 17 7 13 0 12C7 11 11 7 12 0Z" fill="currentColor" />
          </svg>
        );
      })}
    </span>
  );
}

export function ElapsedTimer({ className }: { className?: string }) {
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    const started = performance.now();
    const id = window.setInterval(() => setElapsed((performance.now() - started) / 1000), 100);
    return () => window.clearInterval(id);
  }, []);
  return <span className={cn('font-mono text-caption-1-regular text-text-tertiary tabular-nums', className)}>{elapsed.toFixed(1)}s</span>;
}

/** Dot-grid (wave) or sparkles (stars) indicator, a shimmering label and an elapsed timer. */
export function AgentThinking({
  variant = 'wave',
  label = 'Thinking',
  tone,
  showTimer = true,
  small,
  className,
}: {
  variant?: 'wave' | 'stars';
  label?: ReactNode;
  tone?: keyof typeof TONES;
  showTimer?: boolean;
  small?: boolean;
  className?: string;
}) {
  const color = TONES[tone ?? (variant === 'stars' ? 'subtle' : 'default')];
  return (
    <div role="status" className={cn('flex items-center gap-2.5', className)} style={{ color, '--sui-agent-thinking-tone': color } as CSSProperties}>
      {variant === 'wave' ? <WaveDots /> : <Stars />}
      <span className={cn('sui-agent-thinking-label', small ? 'text-body-2-medium' : 'text-body-medium')}>{label}</span>
      {showTimer && <ElapsedTimer />}
    </div>
  );
}

/* ------------------------------------------------------------------ Composer surface */

/**
 * The composer's surface: border, background and shadow, drawn behind the wrapped composer so it stays
 * transparent. `radius` defaults to a full pill. Busy is shown by the composer itself (Stop, Agent Thinking),
 * so `active` paints nothing; it stays in the signature for the composers that pass it.
 */
export function ComposerLoader({ radius, children, className, surfaceClassName }: { active: boolean; radius?: number; children: ReactNode; className?: string; surfaceClassName?: string }) {
  return (
    <div className={cn('relative', className)}>
      <span
        aria-hidden
        className={cn('absolute inset-0 border border-border-button-default bg-background-primary-default shadow-xs', surfaceClassName)}
        style={{ borderRadius: radius ?? 9999 }}
      />
      <div className="relative">{children}</div>
    </div>
  );
}

/* ------------------------------------------------------------------ Agent Log */

/**
 * The agent-log trail: each row blurs in under a curved guide that branches off a 1px trunk.
 * Rows are plain children; the last row's trunk stops at its branch.
 */
export function AgentLog({ children, className }: { children: ReactNode[]; className?: string }) {
  return (
    <ul className={cn('flex flex-col', className)}>
      {children.map((child, i) => (
        <li key={i} className="tpl-reveal relative ps-4">
          <span aria-hidden className="absolute inset-y-0 start-0 w-3 text-foreground-icon-quaternary">
            <svg width="12" height="15" viewBox="0 0 12 15" fill="none" className="absolute top-0 start-0">
              <path d="M0.5 0 V8 Q0.5 14 6.5 14 H11.5" stroke="currentColor" pathLength={1} className="tpl-guide" />
            </svg>
            {i < children.length - 1 && <span className="absolute top-2 bottom-0 start-0 w-px origin-top bg-current" />}
          </span>
          <div className="py-[3px]">{child}</div>
        </li>
      ))}
    </ul>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import { CAT_JPG as cat, CODE_ICON as codeIcon, DOC_DARK_ICON as docDarkIcon, DOC_ICON as docIcon, SHEET_ICON as sheetIcon, SLIDES_ICON as slidesIcon, VIDEO_ICON as videoIcon } from './attachments-assets';

/* Composer Attachments: a strip of 56px tiles above
 * the prompt. Images fill the tile and get a frosted white dismiss; the other five kinds carry the kit's 24px
 * plugin icons over a 9px file name. A queued file scales in, an accent ring draws clockwise around the tile
 * while a 9px percentage counts up in the corner, then at 100 the percentage blurs out and the dismiss blurs in
 * on the same spot. Uploads are simulated (defaults: 1100 ms each, 240 ms apart). */

export type AttachmentKind = 'image' | 'document' | 'spreadsheet' | 'presentation' | 'code' | 'video';
export interface Attachment {
  id: string;
  name: string;
  kind: AttachmentKind;
  src?: string;
  /** 0–100 while uploading; undefined once landed. */
  progress?: number;
}

const ICONS: Record<Exclude<AttachmentKind, 'image'>, { light: string; dark?: string }> = {
  document: { light: docIcon, dark: docDarkIcon },
  spreadsheet: { light: sheetIcon },
  presentation: { light: slidesIcon },
  code: { light: codeIcon },
  video: { light: videoIcon },
};

/** The demo files, handed out in turn by the + button. */
const SAMPLES: Omit<Attachment, 'id'>[] = [
  { name: 'cat.jpg', kind: 'image', src: cat },
  { name: 'payrollz-2026.docx', kind: 'document' },
  { name: 'timetable.xlsx', kind: 'spreadsheet' },
  { name: 'presentation.key', kind: 'presentation' },
  { name: 'reactypes.tsx', kind: 'code' },
  { name: 'birthday.mp4', kind: 'video' },
];

/** The rounded-rect outline the ring traces, starting top-centre (pathLength 100). */
const RING = 'M 28 1 H 44 A 11 11 0 0 1 55 12 V 44 A 11 11 0 0 1 44 55 H 12 A 11 11 0 0 1 1 44 V 12 A 11 11 0 0 1 12 1 Z';

export function AttachmentTile({ attachment: a, onRemove }: { attachment: Attachment; onRemove?: () => void }) {
  const uploading = a.progress !== undefined;
  const image = a.kind === 'image';
  const icon = a.kind === 'image' ? null : ICONS[a.kind];
  return (
    <div className="tpl-tile-in">
      <div title={a.name} className="relative size-14 shrink-0 rounded-xl border border-composer-panel-tile-border">
        {image ? (
          <img alt={a.name} src={a.src} className={cn('absolute inset-0 size-full rounded-[11px] object-cover transition-opacity duration-300 ease-out', uploading && 'opacity-60')} />
        ) : (
          <div className={cn('transition-opacity duration-300 ease-out', uploading && 'opacity-60')}>
            <img alt="" aria-hidden="true" src={icon!.light} className={cn('absolute start-[3px] top-1 size-6', icon!.dark && 'dark:hidden')} />
            {icon!.dark && <img alt="" aria-hidden="true" src={icon!.dark} className="absolute start-[3px] top-1 hidden size-6 dark:block" />}
            <span className="absolute start-1.5 top-9 max-w-[44px] truncate text-[9px] leading-[15px] font-medium tracking-[0.2px] text-text-secondary">{a.name}</span>
          </div>
        )}
        <svg aria-hidden="true" viewBox="0 0 56 56" className={cn('pointer-events-none absolute -inset-px size-14 transition-opacity duration-300 ease-out', uploading ? 'opacity-100' : 'opacity-0')}>
          <path d={RING} fill="none" stroke="var(--color-accent-400)" strokeWidth="2" strokeLinecap="round" pathLength={100} strokeDasharray={`${uploading ? a.progress : 102} 200`} className="transition-[stroke-dasharray] duration-200 ease-linear" />
        </svg>
        <span
          aria-hidden="true"
          className={cn(
            'pointer-events-none absolute end-[3px] top-[3px] text-[9px] leading-4 font-medium tabular-nums transition-[opacity,filter] duration-300 ease-out',
            image ? 'text-white' : 'text-accent-500',
            uploading ? 'opacity-100 blur-[0px]' : 'opacity-0 blur-[3px]',
          )}
        >
          {Math.round(a.progress ?? 100)}%
        </span>
        <button
          type="button"
          aria-label={`Remove ${a.name}`}
          onClick={onRemove}
          disabled={uploading}
          className={cn(
            'ease absolute start-[35px] top-[3px] inline-flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-full outline-none select-none transition-[opacity,filter,color] duration-300 ease-out focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2',
            image ? 'bg-white/50 text-white backdrop-blur-[2px] hover:text-white' : 'bg-background-tertiary-default/50 text-foreground-icon-secondary hover:text-text-primary',
            uploading ? 'pointer-events-none opacity-0 blur-[3px]' : 'opacity-100 blur-[0px]',
          )}
        >
          <svg width="6.8" height="6.8" viewBox="0 0 6.8 6.8" fill="none" aria-hidden="true">
            <path d="M0.57 0.57L6.23 6.23" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
            <path d="M6.23 0.57L0.57 6.23" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
          </svg>
        </button>
      </div>
    </div>
  );
}

/** The strip above the prompt; collapses to nothing when empty. */
export function AttachmentStrip({ attachments, onRemove, className }: { attachments: Attachment[]; onRemove: (id: string) => void; className?: string }) {
  return (
    <div className={cn('grid transition-[grid-template-rows,opacity] duration-300 ease-out', attachments.length ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0')}>
      <div className="min-h-0 overflow-hidden">
        <div className={cn('flex flex-wrap items-start gap-2 pb-1', className)}>
          {attachments.map((a) => (
            <AttachmentTile key={a.id} attachment={a} onRemove={() => onRemove(a.id)} />
          ))}
        </div>
      </div>
    </div>
  );
}

let seq = 0;

/**
 * The upload queue: `add()` queues the next sample file at progress 0; one file uploads at a time
 * over `uploadDuration`, then the next starts after `uploadGap`.
 */
export function useAttachments({ uploadDuration = 1100, uploadGap = 240 } = {}) {
  const [files, setFiles] = useState<Attachment[]>([]);
  const next = useRef(0);
  const add = useCallback(() => {
    const s = SAMPLES[next.current++ % SAMPLES.length];
    setFiles((f) => [...f, { ...s, id: `att-${++seq}`, progress: 0 }]);
  }, []);
  const remove = useCallback((id: string) => setFiles((f) => f.filter((x) => x.id !== id)), []);
  const clear = useCallback(() => setFiles([]), []);

  // Drive the first file still uploading; when it lands the effect re-runs for the next one.
  const active = files.find((f) => f.progress !== undefined);
  useEffect(() => {
    if (!active) return;
    const id = active.id;
    // Progress is read off the clock, not counted per frame: an interval (unlike rAF) keeps running in a
    // background tab, so an upload started there still lands on time.
    const start = performance.now() + (active.progress === 0 ? uploadGap : 0);
    const timer = window.setInterval(() => {
      const p = Math.max(0, Math.min(100, ((performance.now() - start) / uploadDuration) * 100));
      setFiles((f) => f.map((x) => (x.id === id ? { ...x, progress: p >= 100 ? undefined : p } : x)));
      if (p >= 100) window.clearInterval(timer);
    }, 16);
    return () => window.clearInterval(timer);
    // Only restart when a different file becomes the active upload.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active?.id, uploadDuration, uploadGap]);

  return { files, add, remove, clear };
}

/* Composer Attachments sample assets, inlined as data URIs so the kit installs as plain text files and
 * works the same under Vite, Next.js or any bundler: the demo cat photo and the five 24px plugin icons. */
export const CAT_JPG = "data:image/jpeg;base64,";
export const DOC_ICON = "data:image/svg+xml;base64,";
export const DOC_DARK_ICON = "data:image/svg+xml;base64,";
